mapper.select:
SELECT e.* FROM public.nocode_task_entry_record e
JOIN public.nocode_task_instance t ON t.id=e.task_id AND t.deleted=0
JOIN public.nocode_handling_request r ON r.id::text=e.business_json::jsonb->>'requestId' AND r.deleted=0
WHERE e.deleted=0 AND e.creator=#{actor} AND r.creator=#{actor} AND t.assignee_id::text=#{actor}
AND r.id::text=#{request}
ORDER BY e.create_time DESC,e.id DESC LIMIT 1
